{
  "technical_and_design_decisions": [
    "Implement all code in Go, consistent with the existing Hyperledger Fabric codebase, using gRPC for inter-component APIs (orderer broadcast/deliver, peer CLI to peer node).",
    "Solo orderer (U4): implement a minimal Atomic Broadcast service with a buffered ingress channel, a single goroutine performing batch/block cutting (by max message count and batch timeout), and an in-RAM ledger supporting seek so Deliver clients can reconnect and resume from a given block number; no persistence or multi-node consensus.",
    "Lifecycle system chaincode (U2): implement LSCC as a system chaincode registered at peer startup; it stores chaincode deployment metadata and deployment policies on the ledger and exposes lifecycle operations used by deploy/upgrade flows.",
    "Chaincode friendly naming (U1): chaincode is identified by a human-readable unique name carried in the chaincode deployment spec and accepted by deploy/invoke/query interfaces (CLI, SDK, REST/gRPC), replacing raw hash-based IDs in developer workflows.",
    "State cache (U6): add an in-memory, version-aware state cache in front of the state database on the endorser/committer path so submitters can quickly build read-write sets; cache entries are invalidated at block commit time.",
    "Standalone CLI (U8): extract peer commands into a separate client component that depends only on gRPC client libraries and protobuf definitions (no RocksDB or peer internals), cross-compiled and distributed as platform-specific binaries for Linux, macOS, and Windows.",
    "Documentation (U3, U7) authored in the repo (reStructuredText/Markdown) and published so it is discoverable from hyperledger.org; GitHub (U5) is a read-only mirror of the canonical Gerrit repository."
  ],
  "assumptions": [
    "A single experienced Go developer, already familiar with the Hyperledger Fabric codebase, performs all work; estimates are effort in workdays, not elapsed time.",
    "Development workstations, Gerrit access, CI infrastructure, and the existing Fabric baseline are already available; no environment setup time is required.",
    "The solo orderer is required to be in-memory only (no on-disk persistence or crash recovery), as stated in U4.",
    "For U5 and U7, necessary accounts, permissions, and web-site/mirror hosting from the Hyperledger foundation are granted; only the developer's own setup effort is counted.",
    "Each implementation activity includes its own unit testing; cross-feature integration and system testing is estimated as a separate activity.",
    "Scope is limited to the functionality in the eight user stories; production hardening, large-scale performance tuning, and HA ordering (e.g., Kafka) are out of scope.",
    "Documentation is written in English only; no translation effort is included.",
    "An allowance for code review rework and release packaging is included in the final hardening activity."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Increment architecture and design",
      "activity_description": "Analyze the eight user stories, define interfaces (chaincode naming model, LSCC API, orderer broadcast/deliver API, state cache API, standalone CLI structure), and produce short design notes reviewed before coding.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2",
      "activity_name": "U1: Chaincode friendly naming",
      "activity_description": "Add support for human-friendly chaincode names in the chaincode deployment spec and ID handling, update deploy/invoke/query paths (CLI, SDK, gRPC) to accept the name, and add unit tests.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A3",
      "activity_name": "U2: Lifecycle system chaincode (LSCC)",
      "activity_description": "Implement the system chaincode registration framework and the LSCC itself: lifecycle operations for deploy/upgrade, storage of chaincode metadata and deployment policies on the ledger, policy evaluation hooks, and unit tests.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A4",
      "activity_name": "U3: Upgrade flow documentation",
      "activity_description": "Write developer documentation covering chaincode upgrade flows end to end, including examples and compatibility notes.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A5",
      "activity_name": "U4: Solo ordering service",
      "activity_description": "Implement the solo orderer: gRPC Broadcast ingress into a buffered channel, single-threaded batch/block cutting, an in-RAM ledger with seek support, gRPC Deliver with disconnection/reconnection and history retrieval, configuration, logging, and unit tests.",
      "most_likely_effort": 25
    },
    {
      "activity_id": "A6",
      "activity_name": "U5: GitHub mirror of the code",
      "activity_description": "Configure automated replication of the canonical Gerrit repository to a public read-only GitHub mirror, verify synchronization, and document the mirror location for developers.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A7",
      "activity_name": "U6: State cache for rw-set building",
      "activity_description": "Implement a version-aware in-memory state cache in front of the state database for the endorser/submitter path, including commit-time invalidation, concurrency handling, basic benchmarks, and unit tests.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A8",
      "activity_name": "U7: Documentation discoverability",
      "activity_description": "Reorganize the existing documentation set, wire publication so Fabric docs are easily found from hyperledger.org alongside other Hyperledger projects, and verify navigation and links.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A9",
      "activity_name": "U8: Standalone cross-platform CLI",
      "activity_description": "Extract peer CLI commands into a separate component depending only on gRPC client libraries (removing RocksDB and peer-internal dependencies), refactor command wiring, cross-compile and package binaries for Linux, macOS, and Windows, add install docs and tests.",
      "most_likely_effort": 15
    },
    {
      "activity_id": "A10",
      "activity_name": "Integration and system testing",
      "activity_description": "End-to-end testing of the increment: bring up a network with the solo orderer, deploy/invoke/upgrade chaincode by friendly name via LSCC using the standalone CLI on multiple platforms, exercise state cache behavior, and fix defects found.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A11",
      "activity_name": "Hardening, review rework and release packaging",
      "activity_description": "Address code review feedback, update CI/build jobs for the new components and mirror, finalize release notes, and package the increment for delivery.",
      "most_likely_effort": 5
    }
  ],
  "reported_total": {
    "most_likely_effort": 116
  }
}

